import{_ as a,o as r,c as o,ag as e}from"./chunks/framework.D2veAa-g.js";const p=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-操作系统-文件管理基础","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-操作系统-文件管理基础"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/文件管理基础.md","filePath":"综合知识/系统基础/操作系统/文件管理基础.md","lastUpdated":null}'),d={name:"综合知识/系统基础/操作系统/文件管理基础.md"};function l(n,t,h,i,s,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 文件逻辑结构与物理结构</li><li>[ ] 存取方法（顺序/随机）</li><li>[ ] 文件属性（R/A/S/H）</li><li>[ ] 存取控制与硬链接</li><li>[ ] 链式存储与成组分解</li><li>[ ] 位示图</li><li>[ ] 文件存储空间管理</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="文件概述" tabindex="-1">文件概述 <a class="header-anchor" href="#文件概述" aria-label="Permalink to &quot;文件概述&quot;">​</a></h3><p>文件的逻辑结构：有结构的记录式文件、无结构的流式文件。</p><p>文件的物理结构（在物理存储设备上的存放方法）：</p><table tabindex="0"><thead><tr><th>结构</th><th>特点</th></tr></thead><tbody><tr><td>连续结构</td><td>逻辑连续的文件信息依次存放在连续物理块上</td></tr><tr><td>链接结构</td><td>存放在不连续物理块，每块有指针指向下一块</td></tr><tr><td>索引结构</td><td>存放在不连续物理块，系统建立索引表记录逻辑块号→物理块号映射</td></tr><tr><td>多级索引</td><td>索引表占用一个或多个物理块</td></tr></tbody></table><blockquote><p>⚠️ 文件物理结构<strong>不包括散列结构</strong>。连续结构支持快速随机访问但<strong>易产生碎片</strong>。</p></blockquote><p>存取方法：顺序存取、随机存取。</p><blockquote><p>⚠️ 顺序存取的效率<strong>不一定</strong>高于随机存取，取决于实际场景。文件可同时支持两种存取方式。</p></blockquote><h3 id="索引文件结构" tabindex="-1">索引文件结构 <a class="header-anchor" href="#索引文件结构" aria-label="Permalink to &quot;索引文件结构&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/索引文件结构.html">架构师-备考 综合知识-系统基础-操作系统-索引文件结构</a></p><h3 id="文件目录" tabindex="-1">文件目录 <a class="header-anchor" href="#文件目录" aria-label="Permalink to &quot;文件目录&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/文件目录.html">架构师-备考 综合知识-系统基础-操作系统-文件目录</a></p><h3 id="文件属性" tabindex="-1">文件属性 <a class="header-anchor" href="#文件属性" aria-label="Permalink to &quot;文件属性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：R=只读、A=归档、S=系统文件、H=隐藏。</p></blockquote><table tabindex="0"><thead><tr><th>属性</th><th>含义</th></tr></thead><tbody><tr><td><strong>R</strong></td><td>只读文件</td></tr><tr><td><strong>A</strong></td><td>归档文件</td></tr><tr><td><strong>S</strong></td><td>系统文件</td></tr><tr><td><strong>H</strong></td><td>隐藏文件</td></tr></tbody></table><h3 id="存取控制与硬链接" tabindex="-1">存取控制与硬链接 <a class="header-anchor" href="#存取控制与硬链接" aria-label="Permalink to &quot;存取控制与硬链接&quot;">​</a></h3><blockquote><p>🎯 一句话结论：密码保护<strong>不属于</strong>存取控制类型。硬链接指向<strong>同一个 inode</strong>。</p></blockquote><p><strong>存取控制类型</strong>：存取控制矩阵、存取控制表、用户权限表。⚠️ <strong>密码保护</strong>不属于存取控制类型（属于密码保护类型）。</p><p><strong>硬链接</strong>：两个文件目录项指向<strong>同一个索引节点</strong>（inode），不是创建新文件实体，必须位于同一文件系统。</p><h3 id="链式存储与成组分解" tabindex="-1">链式存储与成组分解 <a class="header-anchor" href="#链式存储与成组分解" aria-label="Permalink to &quot;链式存储与成组分解&quot;">​</a></h3><blockquote><p>🎯 一句话结论：成组分解 = 多记录打包存入一块；读取时先读块再分解出目标记录。</p></blockquote><p>链式存储中，物理块不连续，每块有指针指向下一块。<strong>成组分解技术</strong>：多个逻辑记录打包存入一个物理块；读取时先将物理块读入缓冲区，再分解出目标记录。</p><blockquote><p>计算：磁盘块 4096 字节，记录 2048 字节 → 每块存 2 个记录。访问第 12288 字节 → 12288 / 4096 = <strong>第 3 个磁盘块</strong>（从 0 计数）。</p></blockquote><h3 id="位示图" tabindex="-1">位示图 <a class="header-anchor" href="#位示图" aria-label="Permalink to &quot;位示图&quot;">​</a></h3><blockquote><p>🎯 一句话结论：位示图每一位对应一个物理块，1 = 已占用，0 = 空闲。用于管理磁盘空闲块。</p></blockquote><h3 id="文件存储空间管理" tabindex="-1">文件存储空间管理 <a class="header-anchor" href="#文件存储空间管理" aria-label="Permalink to &quot;文件存储空间管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>原理</th></tr></thead><tbody><tr><td>空闲区表</td><td>为每个连续空闲区建立表项，适用于连续文件结构</td></tr><tr><td>位示图 (Bitmap)</td><td>每一位对应一个物理块，0=空闲，1=占用</td></tr><tr><td>空闲块链</td><td>每个空闲块指向下一个空闲块，链表头指针放在特定位置</td></tr><tr><td>成组链接法</td><td>空闲块分组（如 100 块/组），每组第一块登记下一组盘块号和空闲块总数</td></tr></tbody></table><blockquote><p><strong>位示图计算</strong>：物理块号 N 在第 <code>⌊N/字长⌋</code> 个字中描述（从 0 编号即为第 <code>⌊N/字长⌋</code> 个字）。磁盘容量/物理块大小 = 物理块总数 → 除以字长 = 位示图所需字数。</p></blockquote>',30)])])}const u=a(d,[["render",l]]);export{p as __pageData,u as default};
